import { categoryMeta, isBusinessCategory, type BusinessCategory } from './business-categories';
import { defaultBusinessHours, getBusinessHours, saveBusinessHours, slotTimesForDate, type BusinessHours } from './business-hours';

type Role = 'owner' | 'manager' | 'staff';
type Member = { businessId: string; role: Role; businessName: string };
type Business = { category: BusinessCategory; name: string; ownerName: string; slug: string; whatsapp: string; location: string; tagline: string; about: string; bookingEnabled: boolean; timezone: string; slotInterval: number; status: 'active' | 'suspended' | 'pending_deletion'; createdBy: string; createdAt: number };
type Service = { name: string; price: number; duration: number; description: string; active: boolean; rebookDays: number; createdAt: number };
type Appointment = { customerId?: string; customerName: string; customerPhone: string; serviceId: string; serviceName: string; startsAt: string; endsAt: string; amount: number; status: 'Requested'|'Confirmed'|'Completed'|'Cancelled'|'No Show'; source: string; notes: string; depositStatus?: 'not_required'|'pending'|'paid'|'waived'; depositAmount?: number; attributionCampaignId?: string; createdAt: number; updatedAt: number };
type Customer = { name: string; phone: string; phoneNormalized: string; email: string; source: string; notes: string; marketingStatus?: 'unknown'|'opted_in'|'opted_out'; createdAt: number };
type Campaign = { createdAt: number; objective: string; serviceId: string; serviceName: string; audience: string; content: string; publicUrl: string; status: 'Draft'|'Published'; landingPublished?: boolean };
type Storefront = { businessId: string; category?: BusinessCategory; name: string; ownerName: string; slug: string; whatsapp: string; location: string; tagline: string; about: string; bookingEnabled: boolean; timezone: string; slotInterval: number; services: Array<Service & { id: string }>; portfolio: PublicPortfolioItem[]; reviews?: PublicReview[]; brand?: PublicBrand; bookingPolicy?: BookingPolicy; businessHours?: BusinessHours };


function cleanSlug(value: string) { return String(value || '').toLowerCase().trim().replace(/['’]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 48); }
function phone(value: string) { return String(value || '').replace(/\D/g, '').slice(0, 15); }
function minutes(value: string) { const [h, m] = value.split(':').map(Number); return h * 60 + m; }
function timeString(total: number) { return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`; }
function overlaps(aStart: string, aEnd: string, bStart: string, bEnd: string) { return aStart < bEnd && aEnd > bStart; }
function safeText(value: unknown, max = 300) { return String(value ?? '').trim().slice(0, max); }
function publicPath(slug: string) { return `storefronts/${cleanSlug(slug)}.json`; }
function customerIndexPath(businessId: string, normalized: string) { return `indexes/${businessId}/phones/${normalized}.json`; }
async function readStorefront(slug: string): Promise<Storefront | null> { const normalized = cleanSlug(slug); if (!normalized) return null; const [file] = await storage.read([publicPath(normalized)]); if (file?.content) { try { return await hydratePublicStorefrontMedia(JSON.parse(file.content) as Storefront); } catch { return null; } } return null; }
async function memberships(userId: string) { return (await db.list<Member>(`memberships:${userId}`, { limit: 20 })).items; }
async function requireMember(userId: string, businessId: string, roles?: Role[]) { const member = (await memberships(userId)).find(item => item.businessId === businessId) || null; if (!member || (roles && !roles.includes(member.role))) return null; return member; }
async function getBusiness(businessId: string) { const [business] = await db.get<Business>('businesses', [businessId]); return business ? { id: businessId, ...business, category: isBusinessCategory(business.category) ? business.category : 'mixed' as BusinessCategory } : null; }
async function listServices(businessId: string) { return (await db.list<Service>(`services:${businessId}`, { limit: 100 })).items.filter(item => item.active !== false); }
async function cleanupLegacySeedData(businessId:string){const services=(await db.list<Service>(`services:${businessId}`,{limit:100})).items,legacy=services.filter(s=>s.name.trim().toLowerCase()==='signature beauty service'),real=services.filter(s=>s.active!==false&&!legacy.some(x=>x.id===s.id));if(!legacy.length||!real.length)return false;const legacyIds=new Set(legacy.map(s=>s.id)),replacement=real.length===1?real[0]:null;if(replacement){const portfolio=await db.list<{serviceId?:string;serviceName?:string;title?:string;description?:string;published?:boolean;createdAt?:number;updatedAt?:number}>(`portfolio:${businessId}`,{limit:60}),updates=portfolio.items.filter(p=>p.serviceId&&legacyIds.has(p.serviceId)).map(p=>{const{id,...record}=p;return{id,record:{...record,serviceId:replacement.id,serviceName:replacement.name,updatedAt:Date.now()}}});if(updates.length)await db.update(`portfolio:${businessId}`,updates)}const campaigns=await db.list<Campaign>(`campaigns:${businessId}`,{limit:60}),campaignIds=campaigns.items.filter(c=>legacyIds.has(c.serviceId)||c.serviceName.trim().toLowerCase()==='signature beauty service').map(c=>c.id);if(campaignIds.length){await db.delete(`campaigns:${businessId}`,campaignIds);const schedules=await db.list<{campaignId:string}>(`growth-schedules:${businessId}`,{limit:100}),scheduleIds=schedules.items.filter(s=>campaignIds.includes(s.campaignId)).map(s=>s.id);if(scheduleIds.length)await db.delete(`growth-schedules:${businessId}`,scheduleIds)}await db.delete(`services:${businessId}`,legacy.map(s=>s.id));await publishStorefront(businessId);return true}
async function publishStorefront(businessId: string) { const business = await getBusiness(businessId); if (!business) return; const access = await getEntitlements(businessId); if (business.status !== 'active' || !access.canBook) { await storage.delete([publicPath(business.slug)]); return; } const [services, bookingPolicy, marketplace, businessHours] = await Promise.all([listServices(businessId), getBookingPolicy(businessId), getPublicMarketplaceProjection(businessId,business),getBusinessHours(businessId)]); const payload: Storefront = { businessId, category: business.category, name: business.name, ownerName: business.ownerName, slug: business.slug, whatsapp: business.whatsapp, location: business.location, tagline: business.tagline, about: business.about, bookingEnabled: business.bookingEnabled && access.canBook, timezone: business.timezone, slotInterval: business.slotInterval, services, portfolio: marketplace.portfolio, reviews: marketplace.reviews, brand: marketplace.brand, bookingPolicy, businessHours }; const [ok] = await storage.write([{ path: publicPath(business.slug), content: JSON.stringify(payload), contentType: 'application/json' }]); if (!ok) throw new Error('Could not publish storefront'); }
async function ensureCustomer(businessId: string, name: string, rawPhone: string, source: string) { const normalized = phone(rawPhone); if (!normalized) throw new Error('Phone number required'); const [idx] = await storage.read([customerIndexPath(businessId, normalized)]); if (idx?.content) { try { const parsed = JSON.parse(idx.content) as { customerId?: string }; if (parsed.customerId) return parsed.customerId; } catch {} } const access=await getEntitlements(businessId); if(!access.canWrite)throw new Error('Subscription access is paused'); if(access.usage.clients>=access.limits.clients)throw new Error(`${access.plan.name} has reached its client limit`); const [customerId] = await db.add(`customers:${businessId}`, [{ name, phone: rawPhone, phoneNormalized: normalized, email: '', source, notes: '', marketingStatus: 'unknown', createdAt: Date.now() }]); if (!customerId) throw new Error('Could not create client'); await storage.write([{ path: customerIndexPath(businessId, normalized), content: JSON.stringify({ customerId }), contentType: 'application/json' }]); return customerId; }
async function createAppointment(businessId: string, input: { customerId?: string; customerName: string; customerPhone: string; serviceId: string; date: string; time: string; status: Appointment['status']; source: string; notes?: string; businessHours?: BusinessHours; slotInterval?: number }) { const [services, policy] = await Promise.all([listServices(businessId), getBookingPolicy(businessId)]); const service = services.find(item => item.id === input.serviceId); if (!service) throw new Error('Service not found'); const todayJohannesburg = new Date(Date.now() + 2 * 3600000).toISOString().slice(0,10); if (!/^\d{4}-\d{2}-\d{2}$/.test(input.date) || !/^\d{2}:\d{2}$/.test(input.time) || input.date < todayJohannesburg) throw new Error('Choose a valid future date and time'); const serviceDuration=Math.max(15,Math.min(480,Number(service.duration||60))); if(input.businessHours){const valid=slotTimesForDate(input.businessHours,input.date,serviceDuration,input.slotInterval||30),now=new Date(Date.now()+2*3600000),nowMinutes=now.getUTCHours()*60+now.getUTCMinutes();if(!valid.includes(input.time)||(input.date===todayJohannesburg&&minutes(input.time)<=nowMinutes+30))throw new Error('That time is outside the available booking hours')} const startsAt = `${input.date}T${input.time}:00`; const endsAt = `${input.date}T${timeString(minutes(input.time) + serviceDuration)}:00`; const table = `appointments:${businessId}:${startsAt.slice(0,7)}`; const existing = await db.list<Appointment>(table, { limit: 300 }); if (existing.items.filter(item => !['Cancelled','No Show'].includes(item.status)).some(item => overlaps(startsAt, endsAt, item.startsAt, item.endsAt))) throw new Error('That time is no longer available'); const depositAmount = depositForAmount(policy, Number(service.price || 0)); const record: Appointment = { customerId: input.customerId, customerName: safeText(input.customerName, 80), customerPhone: safeText(input.customerPhone, 30), serviceId: service.id, serviceName: service.name, startsAt, endsAt, amount: Number(service.price || 0), status: input.status, source: safeText(input.source, 30), notes: safeText(input.notes, 500), depositStatus: depositAmount > 0 ? 'pending' : 'not_required', depositAmount, createdAt: Date.now(), updatedAt: Date.now() }; const [id] = await db.add(table, [record]); if (!id) throw new Error('Could not save appointment'); await registerPartition(businessId,'appointments',startsAt.slice(0,7)); return { id, ...record }; }
function workspaceMetrics(appointments: Array<Appointment & { id: string }>, customers: Array<Customer & { id: string }>) { const active = appointments.filter(item => item.status !== 'Cancelled'); const completed = active.filter(item => item.status === 'Completed'); const visitCounts = new Map<string, number>(); completed.forEach(item => { if (item.customerId) visitCounts.set(item.customerId, (visitCounts.get(item.customerId) || 0) + 1); }); const repeatClients = [...visitCounts.values()].filter(count => count > 1).length; return { revenue: completed.reduce((sum,item)=>sum+Number(item.amount||0),0), completed: completed.length, confirmed: active.filter(i=>i.status==='Confirmed').length, requested: active.filter(i=>i.status==='Requested').length, clients: customers.length, repeatRate: visitCounts.size ? Math.round((repeatClients / visitCounts.size) * 100) : 0, noShowRate: active.length ? Math.round((active.filter(i=>i.status==='No Show').length / active.length) * 100) : 0 }; }


